CREATE FUNCTION app_reference_scope_guard() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp
  AS $$
  DECLARE
    ref_table text := TG_ARGV[0];
    fk_column text := TG_ARGV[1];
    guard_mode text := TG_ARGV[2];
    ref_id uuid := (to_jsonb(NEW) ->> fk_column)::uuid;
    ref_found boolean;
    ref_scope uuid;
  BEGIN
    IF guard_mode NOT IN ('same', 'same_or_global') THEN
      RAISE EXCEPTION 'app_reference_scope_guard: unknown mode %', guard_mode;
    END IF;
    IF ref_id IS NULL THEN
      RETURN NEW;
    END IF;
    EXECUTE format('SELECT true, workspace_id FROM %I WHERE id = $1', ref_table)
      INTO ref_found, ref_scope USING ref_id;
    IF ref_found IS NULL
       OR (guard_mode = 'same' AND ref_scope IS DISTINCT FROM NEW.workspace_id)
       OR (guard_mode = 'same_or_global' AND ref_scope IS NOT NULL
           AND ref_scope IS DISTINCT FROM NEW.workspace_id) THEN
      RAISE EXCEPTION '%.% references a % outside its scope', TG_TABLE_NAME, fk_column, ref_table
        USING ERRCODE = 'foreign_key_violation';
    END IF;
    RETURN NEW;
  END
  $$;--> statement-breakpoint
CREATE TRIGGER "court_hall_forum_id_scope_guard" BEFORE INSERT OR UPDATE OF workspace_id, "forum_id" ON "court_hall" FOR EACH ROW EXECUTE FUNCTION app_reference_scope_guard('forum', 'forum_id', 'same');--> statement-breakpoint
CREATE TRIGGER "bench_forum_id_scope_guard" BEFORE INSERT OR UPDATE OF workspace_id, "forum_id" ON "bench" FOR EACH ROW EXECUTE FUNCTION app_reference_scope_guard('forum', 'forum_id', 'same');
